func newInsight() unsafe.Pointer { return unsafe.Pointer(new(insight.Insight)) }

func newNInsight(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]insight.Insight, n)))
}

func ptrInsight(p unsafe.Pointer, c int32) any {
	r := (*insight.Insight)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return &r.DetectorKey
	case 4:
		return (*string)(unsafe.Pointer(&r.Category))
	case 5:
		return (*string)(unsafe.Pointer(&r.Severity))
	case 6:
		return (*string)(unsafe.Pointer(&r.Status))
	case 7:
		return &r.DedupeKey
	case 8:
		return &r.Subject
	case 9:
		return &r.Headline
	case 10:
		return &r.Narrative
	case 11:
		return &r.Recommendation
	case 12:
		return &r.Narrated
	case 13:
		return &r.Metrics
	case 14:
		return &r.Links
	case 15:
		return &r.WindowStart
	case 16:
		return &r.WindowEnd
	case 17:
		return &r.DetectedAt
	case 18:
		return &r.StaleAt
	case 19:
		return &r.DismissedAt
	case 20:
		return (*string)(unsafe.Pointer(&r.DismissedByID))
	case 21:
		return &r.DismissReason
	case 22:
		return &r.ModelIdentifier
	case 23:
		return (*string)(unsafe.Pointer(&r.ProviderID))
	case 24:
		return &r.Version
	case 25:
		return &r.CreatedAt
	case 26:
		return &r.UpdatedAt
	}
	return nil
}

func valueInsight(p unsafe.Pointer, c int32) any {
	r := (*insight.Insight)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return r.DetectorKey
	case 4:
		return string(r.Category)
	case 5:
		return string(r.Severity)
	case 6:
		return string(r.Status)
	case 7:
		return r.DedupeKey
	case 8:
		if r.Subject == "" {
			return nil
		}
		return r.Subject
	case 9:
		return r.Headline
	case 10:
		if r.Narrative == "" {
			return nil
		}
		return r.Narrative
	case 11:
		if r.Recommendation == "" {
			return nil
		}
		return r.Recommendation
	case 12:
		return r.Narrated
	case 13:
		if r.Metrics == nil {
			return keel.EmptyJSONArray
		}
		return r.Metrics
	case 14:
		if r.Links == nil {
			return keel.EmptyJSONArray
		}
		return r.Links
	case 15:
		return r.WindowStart
	case 16:
		return r.WindowEnd
	case 17:
		return r.DetectedAt
	case 18:
		return r.StaleAt
	case 19:
		if r.DismissedAt == nil {
			return nil
		}
		return *r.DismissedAt
	case 20:
		if r.DismissedByID == "" {
			return nil
		}
		return string(r.DismissedByID)
	case 21:
		if r.DismissReason == "" {
			return nil
		}
		return r.DismissReason
	case 22:
		if r.ModelIdentifier == "" {
			return nil
		}
		return r.ModelIdentifier
	case 23:
		if r.ProviderID == "" {
			return nil
		}
		return string(r.ProviderID)
	case 24:
		return r.Version
	case 25:
		return r.CreatedAt
	case 26:
		return r.UpdatedAt
	}
	return nil
}

func beforeCreateInsight(ctx context.Context, p unsafe.Pointer) error {
	return (*insight.Insight)(p).BeforeCreate(ctx)
}

var enumCategory = [...]schema.EnumValue{
	{Value: `ServiceQuality`, Label: `Service Quality`, Doc: `CategoryServiceQuality covers service the customer feels — on-time performance, service failures, appointment adherence.`},
	{Value: `CashFlow`, Label: `Cash Flow`, Doc: `CategoryCashFlow covers money earned but not yet collected.`},
	{Value: `CostLeakage`, Label: `Cost Leakage`, Doc: `CategoryCostLeakage covers money the operation is losing quietly: dwell time nobody billed for, empty miles nobody costed.`},
	{Value: `Compliance`, Label: `Compliance`, Doc: `CategoryCompliance covers exposure that takes capacity off the road — credentials and qualifications running out.`},
}

var enumSeverity = [...]schema.EnumValue{
	{Value: `Info`, Label: `Info`},
	{Value: `Warning`, Label: `Warning`},
	{Value: `Critical`, Label: `Critical`},
}

var enumStatus = [...]schema.EnumValue{
	{Value: `Active`, Label: `Active`, Doc: `StatusActive means the condition was present at the last refresh.`},
	{Value: `Dismissed`, Label: `Dismissed`, Doc: `StatusDismissed means a person judged it not worth acting on. The next refresh will find the same condition and must not put the card straight back, so a dismissal suppresses its finding for DismissalSuppression rather than resolving it. It is "not now", not "never": a condition still present months later has earned another look.`},
	{Value: `Resolved`, Label: `Resolved`, Doc: `StatusResolved means a later refresh no longer found the condition. It is set by the system rather than a person.`},
	{Value: `Superseded`, Label: `Superseded`, Doc: `StatusSuperseded means a newer run of the same detector replaced this one with fresher numbers.`},
}

